-- 84 Options Menu: every row is live. Display.* / Cursor.* ask; the runtime
-- applies the change on the next frame, and the line at the foot reads
-- back what the window has. Display.supports() greys out a row the runtime
-- cannot do. The choices are saved and restored. Generated by
-- tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/84-options-menu.scene"
local SLOT = "options_menu"
local PX, PY = 300.0, 20.0
local ROW_Y = { 170.0, 110.0, 50.0, -10.0, -70.0, -130.0, -186.0 }
local LAMP_X, LAMP_Y = -490.0, 32.0
local GREY = { 0.35, 0.35, 0.42 }
local LABEL = { 0.74, 0.71, 0.82 }
local GOLD = { 1.0, 0.83, 0.42 }

local rows = {
    { key = "mode", feature = "fullscreen", values = {
        { "windowed", "WINDOWED" }, { "borderless", "BORDERLESS" }, { "fullscreen", "FULLSCREEN" } } },
    { key = "res", feature = "window_size", values = {} },
    { key = "vsync", feature = "vsync", values = { { true, "ON" }, { false, "OFF" } } },
    { key = "cap", feature = "max_fps", values = {
        { 0, "OFF" }, { 30, "30" }, { 60, "60" }, { 120, "120" }, { 144, "144" } } },
    { key = "cursor", feature = "cursor", values = {
        { "default", "SYSTEM" }, { "pointer", "POINTER" }, { "crosshair", "CROSSHAIR" },
        { "quill", "QUILL" }, { "hidden", "HIDDEN" } } },
    { key = "confine", feature = "cursor_confine", values = { { false, "OFF" }, { true, "ON" } } },
    { key = "reset" },
}
local pick = { mode = 1, res = 1, vsync = 1, cap = 1, cursor = 1, confine = 1 }
local captions = true
local sel = 1
local labels, values, arrows = {}, {}, {}
local highlight, readout, beam, glow, seas = nil, nil, nil, nil, {}
local hy, t, frames, fps_t, fps, flash = ROW_Y[1], 0, 0, 0, 0, {}

local function apply(key)
    local r
    for _, row in ipairs(rows) do if row.key == key then r = row end end
    local v = r.values[pick[key]]
    if v == nil then return end
    v = v[1]
    if key == "mode" then Display.set_mode(v)
    elseif key == "res" then Display.set_size(v[1], v[2])
    elseif key == "vsync" then Display.set_vsync(v)
    elseif key == "cap" then Display.set_max_fps(v)
    elseif key == "confine" then Cursor.set_confined(v)
    elseif key == "cursor" then
        Cursor.set_visible(v ~= "hidden")
        if v == "quill" then Cursor.set_image("sprites/options/quill.png", 2, 30)
        elseif v ~= "hidden" then Cursor.set_icon(v) end
    end
end

local function save()
    local s = {}
    for key, i in pairs(pick) do s[key] = i end
    Save.set(SLOT, "picks", s)
    Save.commit(SLOT)
end

local function supported(r)
    return r.feature == nil or Display.supports(r.feature)
end

local function change(i, step)
    local r = rows[i]
    if r.key == "reset" then
        for key, _ in pairs(pick) do pick[key] = 1 end
        Display.set_mode("windowed")
        Display.set_max_fps(-1)
        for _, row in ipairs(rows) do if row.values then apply(row.key) end end
        save()
        for k = 1, #rows do flash[k] = 0.4 end
        return
    end
    if not supported(r) or #r.values == 0 then return end
    pick[r.key] = (pick[r.key] - 1 + step) % #r.values + 1
    apply(r.key)
    save()
    flash[i] = 0.4
end

local function resolutions()
    local list = {}
    for _, m in ipairs(Display.get_resolutions()) do
        if #list < 8 then list[#list + 1] = { { m.w, m.h }, m.w .. " x " .. m.h } end
    end
    rows[2].values = list
    if pick.res > #list then pick.res = 1 end
end

local function hit(mx, my)
    for i, y in ipairs(ROW_Y) do
        if math.abs(my - y) < 28 and math.abs(mx - PX) < 260 then return i end
    end
    return nil
end

function init(entity)
    highlight = Entity.find_by_name("Highlight")
    readout = Entity.find_by_name("Readout")
    beam = Entity.find_by_name("Beam")
    glow = Entity.find_by_name("LampGlow")
    seas = { Entity.find_by_name("Sea0") }
    for i = 1, #rows do
        labels[i] = Entity.find_by_name("Label" .. (i - 1))
        values[i] = Entity.find_by_name("Value" .. (i - 1))
        arrows[i] = { Entity.find_by_name("Arrow" .. (i - 1) .. "L"), Entity.find_by_name("Arrow" .. (i - 1) .. "R") }
        flash[i] = 0
    end
    -- What the last run chose.
    local saved = Save.get(SLOT, "picks")
    if type(saved) == "table" then
        for key, i in pairs(saved) do
            if pick[key] ~= nil and type(i) == "number" then pick[key] = math.floor(i) end
        end
        resolutions()
        for _, row in ipairs(rows) do
            if row.values and pick[row.key] > 1 then apply(row.key) end
        end
    end
end

function update(entity, dt)
    nav.tick(SCENE)
    t = t + dt
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if #rows[2].values == 0 then resolutions() end
    -- Keys, and the mouse: hover picks a row, a click on its left half
    -- steps back, on its right half on.
    if Input.is_key_just_pressed("Up") then sel = (sel - 2) % #rows + 1 end
    if Input.is_key_just_pressed("Down") then sel = sel % #rows + 1 end
    if Input.is_key_just_pressed("Left") then change(sel, -1) end
    if Input.is_key_just_pressed("Right") or Input.is_key_just_pressed("Enter") then change(sel, 1) end
    local mx, my = Input.get_mouse_world_position()
    local over = mx and hit(mx, my)
    if over then
        sel = over
        if Input.is_mouse_left_just_pressed() then change(over, (mx < PX + 140 and rows[over].key ~= "reset") and -1 or 1) end
    end
    -- The rows.
    hy = hy + (ROW_Y[sel] - hy) * math.min(1, dt * 14)
    Transform.set_position(highlight, PX, hy)
    for i, r in ipairs(rows) do
        local ok = supported(r)
        flash[i] = math.max(0, flash[i] - dt)
        local f = flash[i] / 0.4
        local c = ok and (i == sel and GOLD or LABEL) or GREY
        Text.set_color(labels[i], c[1], c[2], c[3], 1)
        if values[i] then
            local v = r.values and r.values[pick[r.key]]
            Text.set(values[i], ok and (v and v[2] or "-") or "NOT HERE")
            local k = 1 + f * 0.6
            local vc = ok and GOLD or GREY
            Text.set_color(values[i], math.min(1, vc[1] * k), math.min(1, vc[2] * k), math.min(1, vc[3] * k), 1)
            for _, a in ipairs(arrows[i]) do Sprite.set_color(a, 0.95, 0.8, 0.45, (ok and i == sel) and 1 or 0.25) end
        end
    end
    -- What the window has.
    frames = frames + 1
    fps_t = fps_t + dt
    if fps_t >= 0.5 then
        fps = math.floor(frames / fps_t + 0.5)
        frames, fps_t = 0, 0
    end
    local w, h = Display.get_size()
    local cap = Display.get_max_fps()
    Text.set(readout, string.format("%d x %d   %s   vsync %s   cap %s   %d fps",
        math.floor(w + 0.5), math.floor(h + 0.5), string.upper(Display.get_mode()),
        Display.get_vsync() and "on" or "off", cap == 0 and "off" or tostring(math.floor(cap + 0.5)), fps))
    -- The lighthouse: a beam round the lamp - long when it points across
    -- the frame, short and bright when it points at us - and the sea.
    local a = t * 0.9
    local c, s = math.cos(a), math.sin(a)
    Transform.set_rotation(beam, c >= 0 and -0.04 or math.pi + 0.04)
    Transform.set_scale(beam, math.max(0.05, math.abs(c)), 1)
    Sprite.set_color(glow, 1.0, 0.85, 0.55, 0.35 + 0.65 * math.max(0, s) ^ 4)
    for i, e in ipairs(seas) do
        Transform.set_position(e, -((t * 18) % 256), -210)
    end
end
